    "solution": "Выносим процесс сборки в отдельный объект Builder: он предоставляет методы для пошаговой настройки частей продукта и метод build(), возвращающий готовый объект. Клиент вызывает только нужные шаги в удобном порядке; один и тот же процесс сборки может давать разные представления, а продукт можно сделать неизменяемым — он появляется только целиком в момент build(). Для типовых конфигураций поверх строителя можно завести отдельный класс Director, который знает готовые последовательности шагов (например, buildMinimalRequest() или buildFullRequest()) и избавляет клиента от необходимости помнить порядок вызовов самостоятельно; сам строитель при этом остаётся переиспользуемым для нестандартных сценариев, где Director не подходит. В отличие от Factory Method, который одним вызовом решает, какой класс продукта создать, Builder решает другую задачу — пошагово собрать части одного сложного продукта, и оба паттерна нередко комбинируют: фабрика может возвращать нужный строитель.",
    "code": "interface HttpRequest {\n  readonly method: string;\n  readonly url: string;\n  readonly headers: Record<string, string>;\n  readonly body?: string;\n}\n\nclass HttpRequestBuilder {\n  private headers: Record<string, string> = {};\n  private body?: string;\n  constructor(private method: string, private url: string) {}\n  setHeader(name: string, value: string): this { this.headers[name] = value; return this; }\n  setBody(body: string): this { this.body = body; return this; }\n  build(): HttpRequest { // продукт появляется только целиком, в конце сборки\n    return { method: this.method, url: this.url, headers: { ...this.headers }, body: this.body };\n  }\n}\n\nconst request = new HttpRequestBuilder('POST', '/api/users')\n  .setHeader('Content-Type', 'application/json')\n  .setBody(JSON.stringify({ name: 'Ann' }))\n  .build(); // сложный объект собран пошагово, без телескопического конструктора",
