    "code": "// Наследование: вариант поведения зашит в иерархию классов\nclass TextReport { render(data: string) { return `report(${data})`; } }\nclass PdfTextReport extends TextReport { render(d: string) { return `pdf(${super.render(d)})`; } }\n// нужен ещё сжатый вариант? ZippedPdfTextReport, ZippedHtmlTextReport... — взрыв подклассов\n\n// Композиция: поведение собирается из частей за интерфейсом\ninterface Formatter { format(data: string): string; }\nclass PdfFormatter implements Formatter { format(d: string) { return `pdf(${d})`; } }\nclass HtmlFormatter implements Formatter { format(d: string) { return `html(${d})`; } }\n\nclass Report {\n  constructor(private formatter: Formatter) {} // has-a вместо is-a\n  render(data: string) { return this.formatter.format(data); }\n}\n\nconst report = new Report(new PdfFormatter());\nreport.render('Q3'); // формат меняется заменой части, без новой иерархии",
