    "code": "// Дублирование ЗНАНИЯ: правило «совершеннолетие = 18» живёт в двух местах.\n// При изменении закона одну копию поправят, вторую — забудут.\nfunction canSignContract(age: number) { return age >= 18; }\nfunction canOpenAccount(age: number) { return age >= 18; }\n\n// DRY: единственный авторитетный источник правила\nconst ADULT_AGE = 18;\nconst isAdult = (age: number) => age >= ADULT_AGE;\nfunction canSignContractDry(age: number) { return isAdult(age); }\nfunction canOpenAccountDry(age: number) { return isAdult(age); }\n\n// Случайное сходство — НЕ дублирование знания:\n// числа совпали, но меняются по разным причинам и для разных акторов.\nconst MAX_LOGIN_LENGTH = 20; // ограничение формы регистрации (UX)\nconst MAX_SKU_LENGTH = 20;   // требование складской системы\n// Слить их в одну константу — ложная абстракция:\n// изменение одного правила незаметно сломает другое.",
