    "code": "// Прямой вариант: нулевая цена косвенности, но жёсткая привязка к localStorage\nfunction saveUserDirect(user: { id: string }) {\n  localStorage.setItem(`user:${user.id}`, JSON.stringify(user));\n}\n\n// Абстракция: развязывает код от хранилища, но той же строке логики\n// теперь нужны интерфейс, реализация и внедрение зависимости\ninterface KeyValueStore {\n  set(key: string, value: string): void;\n}\n\nclass LocalStore implements KeyValueStore {\n  set(key: string, value: string) { localStorage.setItem(key, value); }\n}\n\nclass UserRepository {\n  constructor(private store: KeyValueStore) {} // цена: три слоя вместо одной функции\n  save(user: { id: string }) {\n    this.store.set(`user:${user.id}`, JSON.stringify(user));\n  }\n}\n\n// Окупается, только если реализаций реально несколько:\nconst repo = new UserRepository(new LocalStore()); // в тестах — InMemoryStore\nrepo.save({ id: '42' });",
